// ---- story (chapter Ch3 part 3b, ch3b agent 2026-10-07: Sapphire data/maps/MauvilleCity_House2/scripts.inc;
// generators must keep everything from this line on; entries above marked "// story:"). The woman (uid 1) is in
// data/story/ch3b.json; text lines 1-5 (line 0 is the generator's).
// Harbor Mail is no Gen 5 item: Slateport's Mart sells Black 2's Greet Mail in its place (data/hoenn_shops.json, the
// same stand-in as the item balls), so she wants ITEM_GREET_MAIL. The Coin Case is Black 2's own (ITEM_COIN_CASE).
#define T_BuyHarborMail 1
#define T_TradeForCoinCase 2
#define T_IllTrade 3
#define T_UseCoinCase 4
#define T_Disappointing 5
#define H2_WOMAN 1
#define ITEM_HARBOR_MAIL ITEM_GREET_MAIL

H2_Woman:                           // MauvilleCity_House2_EventScript_Woman
    c3_talk
    h_goto_if_set FLAG_RECEIVED_COIN_CASE, L_H2_ReceivedCoinCase
    h_msgbox T_BuyHarborMail        // If I had a Bike, it'd be easy to cycle to Slateport for some shopping. ...
    h_checkitem ITEM_HARBOR_MAIL, 1, C3B_A
    h_goto_if_eq C3B_A, 1, L_H2_AskToTrade
    h_release
L_H2_AskToTrade:                    // MauvilleCity_House2_EventScript_AskToTradeForHarborMail (SE_PIN, "!", delay_48)
    h_closemessage
    h_applymovement H2_WOMAN, Mv_H2_Notice
    h_waitmovement
    h_yesno T_TradeForCoinCase, C3B_A   // Oh! You have Harbor Mail? Will you trade it for a Coin Case?
    h_goto_if_no C3B_A, L_H2_DeclineTrade
    h_msgbox T_IllTrade             // Oh, I'm so happy! Okay, I'll trade you a Coin Case!
    h_closemessage
    h_removeitem ITEM_HARBOR_MAIL, 1, C3B_A
    h_giveitem ITEM_COIN_CASE
    h_setflag FLAG_RECEIVED_COIN_CASE
L_H2_ReceivedCoinCase:
    h_msgbox T_UseCoinCase          // That Coin Case can be used at the Game Corner.
    h_release
L_H2_DeclineTrade:
    h_msgbox T_Disappointing        // Oh, that's disappointing. A Coin Case is needed for the Game Corner.
    h_release

    .balign 4, 0
Mv_H2_Notice:
    emote_exclamation_mark
    delay_16 3
    step_end
    .balign 4, 0
